package com.simibubi.create.test;

import com.simibubi.create.*;
import com.simibubi.create.content.contraptions.*;
import com.simibubi.create.content.contraptions.gantry.*;
import com.simibubi.create.content.contraptions.render.ContraptionEntityRenderer;
import com.simibubi.create.content.kinetics.base.*;
import com.simibubi.create.content.kinetics.gantry.*;
import com.simibubi.create.content.kinetics.motor.CreativeMotorBlock;
import com.simibubi.create.content.kinetics.simpleRelays.ShaftBlock;
import com.simibubi.create.foundation.model.PartialModelRenderState;
import java.util.*;
import java.util.concurrent.atomic.*;
import java.util.function.Predicate;
import net.fabricmc.fabric.api.client.gametest.v1.context.*;
import net.minecraft.client.Minecraft;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.BarrelBlockEntity;
import net.minecraft.world.phys.*;

/** Proposed unexecuted scene: real motor, genuine owner/cargo reload, native rack modes and collision. */
final class GantryRenderingTest {
    private static final BlockPos R=new BlockPos(31003,5,5),P=R.above(),C=P.above(),M=R.west(),POWER=R.north();
    private static final int LENGTH=9;
    static void run(ClientGameTestContext context,TestSingleplayerContext world){
        var server=world.getServer();server.runCommand("gamemode spectator @p");server.runCommand("tp @p 31008.5 10 12.5");
        context.waitFor(client->Math.abs(client.player.getX()-31008.5)<.1&&client.level.isLoaded(R.east(LENGTH))&&client.level.isLoaded(R.west(2)),400);
        server.runCommand("fill 30999 4 -1 31016 4 16 minecraft:smooth_quartz");
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();for(int i=0;i<LENGTH;i++)level.setBlockAndUpdate(R.east(i),AllBlocks.GANTRY_SHAFT.defaultBlockState().setValue(GantryShaftBlock.FACING,Direction.EAST));level.setBlockAndUpdate(P,AllBlocks.GANTRY_CARRIAGE.defaultBlockState().setValue(GantryCarriageBlock.FACING,Direction.UP).setValue(GantryCarriageBlock.AXIS_ALONG_FIRST_COORDINATE,false));level.setBlockAndUpdate(C,Blocks.BARREL.defaultBlockState());var cargo=new ItemStack(Items.DIAMOND,7);cargo.set(DataComponents.CUSTOM_NAME,Component.literal("Native gantry cargo"));((BarrelBlockEntity)level.getBlockEntity(C)).setItem(0,cargo);});
        NativeContraptionFixtures.awaitCaptureReady(context,world,400,R,R.east(LENGTH-1),P,C);
        context.waitFor(client->client.level.getBlockEntity(R) instanceof GantryShaftBlockEntity
            &&client.level.getBlockEntity(R.east(LENGTH-1)) instanceof GantryShaftBlockEntity
            &&client.level.getBlockEntity(P) instanceof GantryCarriageBlockEntity
            &&client.level.getBlockEntity(C) instanceof BarrelBlockEntity,300);
        verifyModels(context);
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();level.setBlockAndUpdate(M,AllBlocks.CREATIVE_MOTOR.defaultBlockState().setValue(CreativeMotorBlock.FACING,Direction.EAST));((KineticBlockEntity)level.getBlockEntity(M)).setGeneratedSpeed(-4);});
        var id=new AtomicReference<UUID>();
        waitServer(context,world,level->{for(var owner:level.getEntitiesOfClass(GantryContraptionEntity.class,new AABB(P).inflate(12)))if(owner.getX()>P.getX()+.125){id.set(owner.getUUID());return true;}return false;},400,"Actual native rack motor did not create and translate its genuine gantry owner");
        context.waitFor(client->find(client,id.get()) instanceof GantryContraptionEntity owner&&owner.getContraption()!=null,300);verifyNativeTrackingPrediction(context,id.get());verifyOwner(context,id.get());verifyServerOwner(world,id.get());lookAtOwner(context,id.get());screenshot(context,"create-vulkan-gantry-native-motor-rack-carriage-cogs-and-owned-front-cargo");
        var initial=new AtomicReference<Double>();server.runOnServer(ignored->initial.set(world.getConnection().getServerLevel().getEntity(id.get()).getX()));
        waitServer(context,world,level->level.getEntity(id.get()) instanceof GantryContraptionEntity owner&&owner.getX()>initial.get()+.125,200,"The same accepted native gantry did not move from its actual supporting rack RPM");
        server.runCommand("tp @p 32400 15 32400");
        waitServer(context,world,level->level.getEntity(id.get())==null&&level.getChunkSource().getChunkNow(R.getX()>>4,R.getZ()>>4)==null&&level.getChunkSource().getChunkNow(R.east(LENGTH-1).getX()>>4,R.getZ()>>4)==null,800,"Actual native gantry owner and both source rack chunks did not unload");
        server.runCommand("tp @p 31008.5 10 12.5");
        waitServer(context,world,level->level.getEntity(id.get()) instanceof GantryContraptionEntity owner&&owner.getContraption()!=null,500,"Original saved native gantry UUID did not return through its own registered entity factory");
        context.waitFor(client->Math.abs(client.player.getX()-31008.5)<.1&&find(client,id.get()) instanceof GantryContraptionEntity owner&&owner.getContraption()!=null,300);verifyServerOwner(world,id.get());verifyOwner(context,id.get());lookAtOwner(context,id.get());screenshot(context,"create-vulkan-gantry-real-native-save-unload-return-original-owner-and-seven-named-diamonds");
        var previousModel=context.computeOnClient(client->client.getModelManager().getModel(GantryClient.COGS));var reload=context.computeOnClient(Minecraft::reloadResourcePacks);context.waitFor(client->reload.isDone()&&client.gui.overlay()==null,600);reload.join();
        context.runOnClient(client->{if(client.getModelManager().getModel(GantryClient.COGS)==previousModel)throw new AssertionError("Native gantry cogs kept a stale baked model after actual resource reload");});verifyOwner(context,id.get());
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();((KineticBlockEntity)level.getBlockEntity(M)).setGeneratedSpeed(-64);});
        waitServer(context,world,level->level.getEntity(id.get()) instanceof GantryContraptionEntity owner&&owner.getX()>P.getX()+2.25,300,"Actual native carrier failed to reach a real middle rack before reversal");
        var forward=new AtomicReference<Double>();server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();forward.set(level.getEntity(id.get()).getX());((KineticBlockEntity)level.getBlockEntity(M)).setGeneratedSpeed(64);});
        waitServer(context,world,level->level.getEntity(id.get()) instanceof GantryContraptionEntity owner&&owner.getX()<forward.get()-.25,200,"Real supporting RPM reversal replaced the native owner or failed to reverse it");verifyServerOwner(world,id.get());lookAtOwner(context,id.get());screenshot(context,"create-vulkan-gantry-real-reversed-rack-rpm-on-saved-native-owner");
        var restored=new AtomicReference<BlockPos>();server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var owner=(GantryContraptionEntity)level.getEntity(id.get());restored.set(owner.getRestorationTransform().apply(BlockPos.ZERO));level.setBlockAndUpdate(POWER,Blocks.REDSTONE_BLOCK.defaultBlockState());});
        waitServer(context,world,level->level.getEntity(id.get())==null&&level.getBlockState(restored.get()).is(AllBlocks.GANTRY_CARRIAGE),300,"Actual powered rack failed to restore the original native carriage and cargo");verifyWorld(world,restored.get());
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();level.setBlockAndUpdate(restored.get().north(),AllBlocks.SHAFT.defaultBlockState().setValue(ShaftBlock.AXIS,Direction.Axis.Z));});
        waitServer(context,world,level->level.getBlockEntity(restored.get()) instanceof GantryCarriageBlockEntity carriage&&carriage.getSpeed()==64&&level.getBlockEntity(restored.get().north()) instanceof KineticBlockEntity output&&output.getSpeed()==64,200,"Actual powered rack-to-pinion kinetic edge did not drive the perpendicular stationary output shaft");
        context.waitFor(client->client.level.getBlockEntity(restored.get()) instanceof GantryCarriageBlockEntity carriage&&carriage.getSpeed()==64,200);
        verifyStationary(context,restored.get());look(context,Vec3.atCenterOf(restored.get()));screenshot(context,"create-vulkan-gantry-real-redstone-mode-native-cogs-and-perpendicular-kinetic-output");
        var wall=restored.get().above().west(2);server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();level.setBlockAndUpdate(wall,Blocks.BEDROCK.defaultBlockState());level.setBlockAndUpdate(POWER,Blocks.AIR.defaultBlockState());});var collided=new AtomicReference<UUID>();var start=restored.get();
        waitServer(context,world,level->{for(var owner:level.getEntitiesOfClass(GantryContraptionEntity.class,new AABB(start).inflate(4)))if(owner.getX()<start.getX()-.1){collided.set(owner.getUUID());return true;}return false;},250,"Actual redstone release with unchanged rack RPM did not resume native translation before collision");
        waitServer(context,world,level->level.getEntity(collided.get())==null,250,"Actual native leading-cell terrain collision failed to restore its moving gantry");
        var finalSeat=new AtomicReference<BlockPos>();server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();if(!level.getBlockState(wall).is(Blocks.BEDROCK))throw new AssertionError("Native gantry collision replaced opposing bedrock");for(int i=0;i<LENGTH;i++){var pos=P.east(i);if(level.getBlockState(pos).is(AllBlocks.GANTRY_CARRIAGE)){if(finalSeat.get()!=null)throw new AssertionError("Native gantry duplicated a physical carriage");finalSeat.set(pos);}}if(finalSeat.get()==null)throw new AssertionError("Native terrain stop lost the physical carriage");});verifyWorld(world,finalSeat.get());look(context,Vec3.atCenterOf(finalSeat.get()));screenshot(context,"create-vulkan-gantry-real-terrain-stop-restores-carriage-and-exact-front-cargo");
        GantryReviewRenderingTest.run(context,world);
    }
    private static void verifyServerOwner(TestSingleplayerContext world,UUID id){world.getServer().runOnServer(ignored->{var level=world.getConnection().getServerLevel();if(!(level.getEntity(id) instanceof GantryContraptionEntity owner)||owner.getType()!=AllEntityTypes.GANTRY_CONTRAPTION||owner.getContraption().getBlocks().size()!=2||!owner.getContraption().getStorage().ownsContents())throw new AssertionError("Original registered native gantry lost its owned carriage/cargo");var cargo=owner.getContraption().getStorage().getAllItemStorages().get(new BlockPos(0,1,0)).getStackInSlot(0);if(!cargo.is(Items.DIAMOND)||cargo.getCount()!=7||!cargo.has(DataComponents.CUSTOM_NAME))throw new AssertionError("Original native gantry cargo/components changed");});}
    private static void verifyWorld(TestSingleplayerContext world,BlockPos carriage){world.getServer().runOnServer(ignored->{var level=world.getConnection().getServerLevel();if(!level.getBlockState(carriage).is(AllBlocks.GANTRY_CARRIAGE)||!(level.getBlockEntity(carriage.above()) instanceof BarrelBlockEntity barrel))throw new AssertionError("Ordinary native carriage/front barrel not restored together");var cargo=barrel.getItem(0);if(!cargo.is(Items.DIAMOND)||cargo.getCount()!=7||!cargo.has(DataComponents.CUSTOM_NAME))throw new AssertionError("Restored native gantry cargo/components changed");for(int i=0;i<LENGTH;i++)if(!level.getBlockState(R.east(i)).is(AllBlocks.GANTRY_SHAFT))throw new AssertionError("Native owner took its stationary supporting rack "+i);});}
    private static void verifyNativeTrackingPrediction(ClientGameTestContext context,UUID id){context.runOnClient(client->{var owner=(GantryContraptionEntity)find(client,id);var before=owner.position();float yaw=owner.getYRot(),pitch=owner.getXRot();owner.moveOrInterpolateTo(net.minecraft.world.entity.PositionPath.of(before.add(3,1,0)),35,20);if(!owner.position().equals(before)||owner.getYRot()!=yaw||owner.getXRot()!=pitch||owner.isInterpolating())throw new AssertionError("Native tracking interpolation competed with the gantry's source double predictor");});}
    private static void verifyModels(ClientGameTestContext context){context.runOnClient(client->{for(var block:List.of(AllBlocks.GANTRY_SHAFT,AllBlocks.GANTRY_CARRIAGE))for(var state:block.getStateDefinition().getPossibleStates()){var model=client.getModelManager().getBlockStateModelSet().get(state);if(model==client.getModelManager().getBlockStateModelSet().missingModel())throw new AssertionError("Missing original gantry model "+state);var mesh=net.fabricmc.fabric.api.client.renderer.v1.Renderer.get().mutableMesh();model.emitQuads(mesh.emitter(),client.level,P,state,net.minecraft.util.RandomSource.create(42),side->false);if(mesh.immutableCopy().size()==0)throw new AssertionError("Empty original gantry mesh "+state);}var shaft=(KineticRenderState)client.getBlockEntityRenderDispatcher().tryExtractRenderState(client.level.getBlockEntity(R),.5f,null,false);if(shaft==null||shaft.model.isEmpty()||shaft.axis!=Direction.Axis.X)throw new AssertionError("Native rack renderer lost its actual moving part/facing mesh");});}
    private static void verifyOwner(ClientGameTestContext context,UUID id){context.runOnClient(client->{if(!(find(client,id) instanceof GantryContraptionEntity owner)||owner.getType()!=AllEntityTypes.GANTRY_CONTRAPTION)throw new AssertionError("Native gantry renderer received a different entity factory");var rendered=((ContraptionEntityRenderer)client.getEntityRenderDispatcher().getRenderer(owner)).createRenderState(owner,.5f);var positions=new HashSet<BlockPos>();rendered.blocks.forEach(block->positions.add(block.pos()));if(rendered.blocks.size()!=2||!positions.equals(Set.of(BlockPos.ZERO,new BlockPos(0,1,0)))||rendered.angle!=0||!rendered.actors.isEmpty())throw new AssertionError("Native gantry body/cargo geometry or source translation frame changed: "+positions);for(var block:rendered.blocks)if(!(block.model() instanceof PartialModelRenderState mesh)||mesh.mesh==null||mesh.mesh.size()==0||block.model().isEmpty())throw new AssertionError("Empty native gantry body/cargo Fabric mesh at "+block.pos());var carriage=rendered.blockEntities.stream().filter(be->be.pos().equals(BlockPos.ZERO)&&be.state() instanceof GantryCarriageRenderer.State).findFirst().orElseThrow(()->new AssertionError("Native moving carriage BE renderer missing"));var state=(GantryCarriageRenderer.State)carriage.state();if(state.cogs.mesh==null||state.cogs.mesh.size()==0||state.cogs.isEmpty()||state.shaft.model.isEmpty())throw new AssertionError("Native moving carriage lost its source gears/output shaft");});}
    private static void verifyStationary(ClientGameTestContext context,BlockPos pos){context.runOnClient(client->{var state=(GantryCarriageRenderer.State)client.getBlockEntityRenderDispatcher().tryExtractRenderState(client.level.getBlockEntity(pos),.5f,null,true);if(state==null||state.cogs.mesh==null||state.cogs.mesh.size()==0||state.cogs.isEmpty()||state.shaft.model.isEmpty()||state.shaft.axis!=Direction.Axis.Z||state.facing!=Direction.UP)throw new AssertionError("Actual powered stationary pinion native gear/shaft state incorrect");});}
    private static Entity find(Minecraft client,UUID id){if(client.level==null)return null;for(var entity:client.level.entitiesForRendering())if(entity.getUUID().equals(id))return entity;return null;}
    private static void lookAtOwner(ClientGameTestContext context,UUID id){look(context,context.computeOnClient(client->find(client,id).position().add(.5,1,.5)));}
    private static void look(ClientGameTestContext context,Vec3 point){var angles=context.computeOnClient(client->{var delta=point.subtract(client.player.getEyePosition());return new Vec2((float)Math.toDegrees(Math.atan2(-delta.x,delta.z)),(float)-Math.toDegrees(Math.atan2(delta.y,Math.hypot(delta.x,delta.z))));});context.getInput().lookAt(angles.x,angles.y);}
    private static void waitServer(ClientGameTestContext context,TestSingleplayerContext world,Predicate<ServerLevel> condition,int ticks,String message){var ready=new AtomicBoolean();for(int i=0;i<ticks&&!ready.get();i++){world.getServer().runOnServer(ignored->ready.set(condition.test(world.getConnection().getServerLevel())));if(!ready.get())context.waitTicks(1);}if(!ready.get())throw new AssertionError(message);}
    private static void screenshot(ClientGameTestContext context,String name){context.waitFor(client->client.gui.overlay()==null,200);context.runOnClient(client->client.gui.hud.getChat().clearMessages(false));context.takeScreenshot(name);}
}
